from typing import List

class Solution:
    def maxSum(self, grid: List[List[int]], limits: List[int], k: int) -> int:
        if k == 0:
            return 0

        candidates = []

        for row, limit in zip(grid, limits):
            if limit <= 0:
                continue

            # Zero values do not affect the sum, so only positives are useful.
            positives = [x for x in row if x > 0]

            if len(positives) > limit:
                positives.sort(reverse=True)
                candidates.extend(positives[:limit])
            else:
                candidates.extend(positives)

        if not candidates:
            return 0

        candidates.sort(reverse=True)
        return sum(candidates[:k])
