def magic_square_test(matrix):
    """
    Return True if the input is a magic square, otherwise False.

    A magic square here is a square matrix where the sums of all rows,
    all columns, and both main diagonals are equal.
    """
    if not isinstance(matrix, (list, tuple)):
        return False

    n = len(matrix)
    if n == 0:
        return False

    for row in matrix:
        if not isinstance(row, (list, tuple)) or len(row) != n:
            return False

    try:
        magic_sum = sum(matrix[0])

        for row in matrix:
            if sum(row) != magic_sum:
                return False

        for col in range(n):
            if sum(matrix[row][col] for row in range(n)) != magic_sum:
                return False

        if sum(matrix[i][i] for i in range(n)) != magic_sum:
            return False

        if sum(matrix[i][n - 1 - i] for i in range(n)) != magic_sum:
            return False
    except (TypeError, ValueError):
        return False

    return True


