class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        x = y = 0
        ans = 0

        for i, ch in enumerate(s, 1):
            if ch == 'N':
                y += 1
            elif ch == 'S':
                y -= 1
            elif ch == 'E':
                x += 1
            else:  # 'W'
                x -= 1

            cur_dist = abs(x) + abs(y)
            changes = min(k, i)

            best = cur_dist + 2 * changes
            if best > i:
                best = i

            if best > ans:
                ans = best

        return ans
