    def isqrt(n):
        if n < 0:
            raise ValueError("isqrt() argument must be non-negative")
        if n == 0:
            return 0

        x = 1 << ((n.bit_length() + 1) // 2)
        while True:
            y = (x + n // x) // 2
            if y >= x:
                return x
            x = y


def find_Index(n: int) -> int:
    """
    Return the index k of the smallest triangular number with n digits.

    Triangular numbers are T(k) = k * (k + 1) // 2.
    The smallest n-digit number is 10 ** (n - 1), so we need the
    smallest k such that T(k) >= 10 ** (n - 1).
    """
    if n < 1:
        return 0

    lower_bound = 10 ** (n - 1)
    two_lower_bound = 2 * lower_bound

    k = isqrt(two_lower_bound)

    if k * (k + 1) < two_lower_bound:
        k += 1

    return k


